PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, domain TEXT, verified INTEGER DEFAULT 0, emergency_contact TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS circles(id INTEGER PRIMARY KEY, name TEXT NOT NULL, domain TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS circle_members(user_id INTEGER, circle_id INTEGER, PRIMARY KEY(user_id,circle_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(circle_id) REFERENCES circles(id));
CREATE TABLE IF NOT EXISTS airports(id INTEGER PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, lat REAL, lng REAL);
CREATE TABLE IF NOT EXISTS zones(id INTEGER PRIMARY KEY, name TEXT NOT NULL, lat REAL, lng REAL, airport_id INTEGER, corridor TEXT, FOREIGN KEY(airport_id) REFERENCES airports(id));
CREATE TABLE IF NOT EXISTS flights(id INTEGER PRIMARY KEY, flight_no TEXT NOT NULL, date TEXT NOT NULL, scheduled TEXT NOT NULL, estimated TEXT NOT NULL, status TEXT DEFAULT 'On time', source TEXT DEFAULT 'simulated');
CREATE TABLE IF NOT EXISTS requests(id INTEGER PRIMARY KEY, user_id INTEGER, flight_id INTEGER, zone_id INTEGER NOT NULL, airport_id INTEGER NOT NULL, luggage_units INTEGER DEFAULT 0, luggage_type TEXT DEFAULT 'none', gender_pref TEXT DEFAULT 'any', circle_pref TEXT DEFAULT 'public', ready_time TEXT NOT NULL, status TEXT DEFAULT 'active', first_name TEXT, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(flight_id) REFERENCES flights(id), FOREIGN KEY(zone_id) REFERENCES zones(id));
CREATE TABLE IF NOT EXISTS pools(id INTEGER PRIMARY KEY, airport_id INTEGER, zone_group TEXT, vehicle_type TEXT, departure_time TEXT, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pool_members(pool_id INTEGER, request_id INTEGER, PRIMARY KEY(pool_id,request_id), FOREIGN KEY(pool_id) REFERENCES pools(id) ON DELETE CASCADE, FOREIGN KEY(request_id) REFERENCES requests(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fare_rates(vehicle_type TEXT PRIMARY KEY, per_km REAL NOT NULL, minimum_fare REAL NOT NULL, night_surcharge REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ratings(id INTEGER PRIMARY KEY, request_id INTEGER, stars INTEGER, comment TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sos_events(id INTEGER PRIMARY KEY, request_id INTEGER, note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contact_messages(id INTEGER PRIMARY KEY, name TEXT, email TEXT, message TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS distance_cache(origin TEXT, destination TEXT, km REAL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(origin,destination));
CREATE TABLE IF NOT EXISTS flight_cache(flight_no TEXT, date TEXT, payload_json TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(flight_no,date));
CREATE INDEX IF NOT EXISTS idx_requests_ready ON requests(airport_id,zone_id,ready_time,status);
CREATE INDEX IF NOT EXISTS idx_pool_members_request ON pool_members(request_id);
CREATE INDEX IF NOT EXISTS idx_events_created ON events(created_at);
